                .createAppSession(UUID.randomUUID(), "inst-rn-mock", 1L).accessToken();

        HttpResponse<String> response =
                HTTP.send(get(streamUri(UUID.randomUUID()), appToken),
                        HttpResponse.BodyHandlers.ofString());

